package com.madtitan94.transactionsparser.feature.settings.data

import android.content.Context
import androidx.credentials.ClearCredentialStateRequest
import androidx.credentials.CredentialManager
import androidx.credentials.exceptions.ClearCredentialException
import com.madtitan94.transactionsparser.core.database.TransactionsDatabase
import com.madtitan94.transactionsparser.core.domain.datasource.SessionStorage
import com.madtitan94.transactionsparser.core.domain.util.DataError
import com.madtitan94.transactionsparser.core.domain.util.EmptyResult
import com.madtitan94.transactionsparser.core.domain.util.Result
import com.madtitan94.transactionsparser.feature.settings.domain.DeleteAccountService
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

class LocalDeleteAccountService(
    private val context: Context,
    private val database: TransactionsDatabase,
    private val sessionStorage: SessionStorage
) : DeleteAccountService {

    override suspend fun deleteAccount(): EmptyResult<DataError.Local> = withContext(Dispatchers.IO) {
        try {
            // Best-effort credential eviction for Credential Manager-based Google sign-in.
            clearCredentialState()
            database.clearAllTables()
            when (sessionStorage.clear()) {
                is Result.Success -> Result.Success(Unit)
                is Result.Error -> Result.Error(DataError.Local.UNKNOWN)
            }
        } catch (e: Exception) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            Result.Error(DataError.Local.UNKNOWN)
        }
    }
}

private suspend fun LocalDeleteAccountService.clearCredentialState() {
    try {
        CredentialManager.create(context).clearCredentialState(
            context,
            ClearCredentialStateRequest()
        )
    } catch (_: ClearCredentialException) {
        // Non-fatal: local account/session data is still removed.
    }
}

