import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import com.madtitan94.transactionsparser.core.designsystem.components.AppAlertDialog
import com.madtitan94.transactionsparser.core.designsystem.components.ListRow
import com.madtitan94.transactionsparser.core.domain.backup.RestoreReport
import com.madtitan94.transactionsparser.core.presentation.ObserveAsEvents
import com.madtitan94.transactionsparser.core.presentation.formatInstantDate
import com.madtitan94.transactionsparser.feature.settings.domain.ThemePreference
import kotlinx.coroutines.launch
import org.koin.androidx.compose.koinViewModel

@Composable
fun SettingsRoot(
    appVersion: String,
    appVersionCode: Int,
    onOpenProfile: () -> Unit,
    onOpenRecentlyDeleted: () -> Unit,
    onOpenCategories: () -> Unit,
    onOpenManageDashboards: () -> Unit,
    onOpenDefaultDashboard: () -> Unit,
    viewModel: SettingsViewModel = koinViewModel()
) {
    val state by viewModel.state.collectAsStateWithLifecycle()
    val snackbarHostState = remember { SnackbarHostState() }
    val context = LocalContext.current
    val scope = rememberCoroutineScope()

    // CreateDocument is the whole permission story for export: the picker the user interacts with
    // *is* the grant, so there is no runtime permission to request or to be denied.
    val exportPicker = rememberLauncherForActivityResult(
        ActivityResultContracts.CreateDocument(CSV_MIME_TYPE)
    ) { uri ->
        viewModel.onAction(
            if (uri == null) {
                SettingsAction.OnExportCancelled
            } else {
                SettingsAction.OnExportDestinationChosen(uri.toString())
            }
        )
    }

    // A second launcher rather than a shared one: CreateDocument takes its MIME type at
    // construction, and offering a backup under text/csv would have the picker suggest the wrong
    // extension and file apps open it in a spreadsheet.
    val backupPicker = rememberLauncherForActivityResult(
        ActivityResultContracts.CreateDocument(JSON_MIME_TYPE)
    ) { uri ->
        viewModel.onAction(
            if (uri == null) {
                SettingsAction.OnBackupCancelled
            } else {
                SettingsAction.OnBackupDestinationChosen(uri.toString())
            }
        )
    }

    // OpenDocument rather than GetContent: it returns a document the app can re-read and does not
    // copy the file, and the picker is again the whole permission story.
    val restorePicker = rememberLauncherForActivityResult(
        ActivityResultContracts.OpenDocument()
    ) { uri ->
        // Backing out of the picker is not an error and needs no message; nothing has started yet.
        if (uri != null) viewModel.onAction(SettingsAction.OnRestoreSourceChosen(uri.toString()))
    }

    ObserveAsEvents(viewModel.events) { event ->
        when (event) {
            is SettingsEvent.ShowMessage -> scope.launch {
                snackbarHostState.showSnackbar(event.message.asString(context))
            }
            is SettingsEvent.LaunchExportPicker -> exportPicker.launch(event.suggestedFileName)
            is SettingsEvent.LaunchBackupPicker -> backupPicker.launch(event.suggestedFileName)
            // Not restricted to application/json: a backup that arrived by email or cloud drive is
            // routinely offered as application/octet-stream, and a filter that hides the user's own
            // file is worse than validating whatever they pick.
            SettingsEvent.LaunchRestorePicker -> restorePicker.launch(arrayOf("*/*"))
        }
    }

    SettingsScreen(
        state = state,
        appVersion = appVersion,
        appVersionCode = appVersionCode,
        snackbarHostState = snackbarHostState,
        onOpenProfile = onOpenProfile,
        onOpenRecentlyDeleted = onOpenRecentlyDeleted,
        onOpenCategories = onOpenCategories,
        onOpenManageDashboards = onOpenManageDashboards,
        onOpenDefaultDashboard = onOpenDefaultDashboard,
        onAction = viewModel::onAction
    )
}

private const val CSV_MIME_TYPE = "text/csv"
private const val JSON_MIME_TYPE = "application/json"

/** Enough to see the shape of the problem; the rest is a number, not a list worth scrolling. */
private const val MAX_LISTED_CONFLICTS = 5

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun SettingsScreen(
    state: SettingsState,
    appVersion: String,
    appVersionCode: Int,
    snackbarHostState: SnackbarHostState,
    onOpenProfile: () -> Unit,
    onOpenRecentlyDeleted: () -> Unit,
    onOpenCategories: () -> Unit,
    onOpenManageDashboards: () -> Unit,
    onOpenDefaultDashboard: () -> Unit,
    onAction: (SettingsAction) -> Unit
) {
    Scaffold(
        topBar = { TopAppBar(title = { Text(stringResource(R.string.settings_title)) }) },
        snackbarHost = { SnackbarHost(snackbarHostState) }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
        ) {
            SettingsRow(
                icon = Icons.Default.Person,
                title = stringResource(R.string.settings_profile),
                supporting = state.email.takeIf { it.isNotBlank() },
                onClick = onOpenProfile
            )
            HorizontalDivider()

            // The design ships two themes rather than one, so there has to be somewhere to choose
            // between them. Defaulting to the system setting is what makes both halves reachable
            // without anyone having to find this row first.
            // Categories left the bottom bar when the design's five slots were spent elsewhere, so
            // this is now the only way to reach it. It sits directly under Profile rather than
            // among the data rows: it is setup, not maintenance.
            SettingsRow(
                icon = Icons.Default.Category,
                title = stringResource(R.string.settings_categories),
                supporting = stringResource(R.string.settings_categories_supporting),
                onClick = onOpenCategories
            )
            HorizontalDivider()

            // Two rows rather than the one "Dashboard layout" row the plan named. They are
            // different decisions: which dashboards exist and in what order is a set, while which
            // one opens first is a single choice among them, and folding them together would put a
            // star and a switch on the same row with no way to express "starred but switched off".
            SettingsRow(
                icon = Icons.Default.DashboardCustomize,
                title = stringResource(R.string.settings_dashboards),
                supporting = stringResource(R.string.settings_dashboards_supporting),
                onClick = onOpenManageDashboards
            )
            HorizontalDivider()

            SettingsRow(
                icon = Icons.Default.Dashboard,
                title = stringResource(R.string.settings_default_dashboard),
                supporting = stringResource(R.string.settings_default_dashboard_supporting),
                onClick = onOpenDefaultDashboard
            )
            HorizontalDivider()

            SettingsRow(
                icon = Icons.Default.DarkMode,
                title = stringResource(R.string.settings_theme),
                supporting = stringResource(state.theme.labelRes),
                onClick = { onAction(SettingsAction.OnThemeClick) }
            )
            HorizontalDivider()

            SettingsRow(
                icon = Icons.Default.FileDownload,
                title = stringResource(R.string.settings_export),
                supporting = stringResource(R.string.settings_export_supporting),
                onClick = { onAction(SettingsAction.OnExportClick) },
                trailing = if (state.isExporting) {
                    { CircularProgressIndicator(Modifier.size(20.dp)) }
                } else {
                    null
                }
            )
            HorizontalDivider()

            // Separate from Export on purpose. Export produces a report to read; this produces a
            // file that can restore the app. Folding them into one row would leave the user
            // guessing which of the two they just got.
            SettingsRow(
                icon = Icons.Default.Backup,
                title = stringResource(R.string.settings_backup),
                supporting = stringResource(R.string.settings_backup_supporting),
                onClick = { onAction(SettingsAction.OnBackupClick) },
                trailing = if (state.isBackingUp) {
                    { CircularProgressIndicator(Modifier.size(20.dp)) }
                } else {
                    null
                }
            )
            HorizontalDivider()

            SettingsRow(
                icon = Icons.Default.Restore,
                title = stringResource(R.string.settings_restore),
                supporting = stringResource(R.string.settings_restore_supporting),
                onClick = { onAction(SettingsAction.OnRestoreClick) },
                // Reading and writing are the two stages with nothing to decide, so they show the
                // same spinner the neighbouring actions use rather than a dialog of their own.
                trailing = if (state.restore.isBusy) {
                    { CircularProgressIndicator(Modifier.size(20.dp)) }
                } else {
                    null
                }
            )
            HorizontalDivider()

            SettingsRow(
                icon = Icons.Default.RestoreFromTrash,
                title = stringResource(R.string.settings_recently_deleted),
                supporting = stringResource(R.string.settings_recently_deleted_supporting),
                onClick = onOpenRecentlyDeleted
            )
            HorizontalDivider()

            // No backend exists yet, so this is deliberately inert rather than hidden — knowing
            // it is coming is more useful than wondering whether the app syncs at all.
            SettingsRow(
                icon = Icons.Default.CloudSync,
                title = stringResource(R.string.settings_syncing),
                supporting = stringResource(R.string.settings_coming_soon),
                onClick = null
            )
            HorizontalDivider()

            SettingsRow(
                icon = Icons.AutoMirrored.Filled.Logout,
                title = stringResource(R.string.settings_logout),
                onClick = { onAction(SettingsAction.OnLogoutClick) }
            )
            HorizontalDivider()

            SettingsRow(
                icon = Icons.Default.DeleteForever,
                title = stringResource(R.string.settings_delete_account),
                supporting = stringResource(R.string.settings_delete_account_supporting),
                onClick = if (state.isDeletingAccount) {
                    null
                } else {
                    { onAction(SettingsAction.OnDeleteAccountClick) }
                },
                trailing = if (state.isDeletingAccount) {
                    { CircularProgressIndicator(Modifier.size(20.dp)) }
                } else {
                    null
                }
            )
            HorizontalDivider()

            Text(
                text = stringResource(R.string.settings_version, appVersion, appVersionCode),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                textAlign = TextAlign.Center,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(24.dp)
            )
        }

        if (state.showLogoutConfirm) {
            AppAlertDialog(
                title = stringResource(R.string.settings_logout_confirm_title),
                message = stringResource(R.string.settings_logout_confirm_message),
                confirmLabel = stringResource(R.string.settings_logout),
                dismissLabel = stringResource(R.string.settings_cancel),
                onConfirm = { onAction(SettingsAction.OnConfirmLogout) },
                onDismiss = { onAction(SettingsAction.OnDismissLogoutConfirm) }
            )
        }

        if (state.showDeleteAccountConfirm) {
            AppAlertDialog(
                title = stringResource(R.string.settings_delete_account_confirm_title),
                message = stringResource(R.string.settings_delete_account_confirm_message),
                confirmLabel = stringResource(R.string.settings_delete_account_confirm_action),
                dismissLabel = stringResource(R.string.settings_cancel),
                onConfirm = { onAction(SettingsAction.OnConfirmDeleteAccount) },
                onDismiss = { onAction(SettingsAction.OnDismissDeleteAccountConfirm) }
            )
        }

        if (state.showThemePicker) {
            ThemePickerDialog(
                selected = state.theme,
                onSelect = { onAction(SettingsAction.OnThemeSelected(it)) },
                onDismiss = { onAction(SettingsAction.OnThemePickerDismissed) }
            )
        }

        RestoreDialogs(
            stage = state.restore,
            signedInEmail = state.email,
            onAction = onAction
        )
    }
}

/** The label shown for a theme choice, both in the row and in the picker. */
private val ThemePreference.labelRes: Int
    get() = when (this) {
        ThemePreference.SYSTEM -> R.string.settings_theme_system
        ThemePreference.LIGHT -> R.string.settings_theme_light
        ThemePreference.DARK -> R.string.settings_theme_dark
    }

/**
 * A single-choice list rather than a switch, because there are three answers and not two — the
 * third, following the device, is the default and cannot be expressed as an on/off.
 *
 * There is no confirm button: picking applies immediately and the theme changes behind the
 * dialog, which is the fastest way to see whether it is the one you wanted.
 */
@Composable
private fun ThemePickerDialog(
    selected: ThemePreference,
    onSelect: (ThemePreference) -> Unit,
    onDismiss: () -> Unit
) {
    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(stringResource(R.string.settings_theme)) },
        text = {
            Column {
                ThemePreference.entries.forEach { preference ->
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier
                            .fillMaxWidth()
                            .selectable(
                                selected = preference == selected,
                                role = Role.RadioButton,
                                onClick = { onSelect(preference) }
                            )
                            .padding(vertical = 12.dp)
                    ) {
                        RadioButton(
                            selected = preference == selected,
                            // The whole row is the target; the button would otherwise be a second,
                            // smaller one sitting inside it.
                            onClick = null
                        )
                        Text(
                            text = stringResource(preference.labelRes),
                            style = MaterialTheme.typography.bodyLarge,
                            modifier = Modifier.padding(start = 12.dp)
                        )
                    }
                }
            }
        },
        confirmButton = {
            TextButton(onClick = onDismiss) {
                Text(stringResource(R.string.settings_theme_done))
            }
        }
    )
}

/**
 * The three points in a restore where the user decides something.
 *
 * Everything shown here is read from a file that has already been fully validated, so the counts
 * are facts rather than estimates — and nothing has been written to the database yet at either of
 * the first two.
 */
@Composable
private fun RestoreDialogs(
    stage: RestoreStage,
    signedInEmail: String,
    onAction: (SettingsAction) -> Unit
) {
    when (stage) {
        is RestoreStage.AccountMismatch -> AppAlertDialog(
            title = stringResource(R.string.settings_restore_account_title),
            message = stringResource(
                R.string.settings_restore_account_message,
                stage.preview.account?.email.orEmpty(),
                signedInEmail
            ),
            confirmLabel = stringResource(R.string.settings_restore_account_continue),
            dismissLabel = stringResource(R.string.settings_cancel),
            onConfirm = { onAction(SettingsAction.OnRestoreAccountAccepted) },
            onDismiss = { onAction(SettingsAction.OnRestoreDismissed) }
        )

        is RestoreStage.Confirm -> AppAlertDialog(
            title = stringResource(R.string.settings_restore_confirm_title),
            message = stringResource(
                R.string.settings_restore_confirm_message,
                formatInstantDate(stage.preview.exportedAtMillis),
                stage.preview.appVersionName,
                stage.preview.summary.transactions,
                stage.preview.summary.payees,
                stage.preview.summary.payeeIdentifiers,
                stage.preview.summary.categories,
                stage.preview.summary.sessions
            ),
            confirmLabel = stringResource(R.string.settings_restore_confirm_action),
            dismissLabel = stringResource(R.string.settings_cancel),
            onConfirm = { onAction(SettingsAction.OnRestoreConfirmed) },
            onDismiss = { onAction(SettingsAction.OnRestoreDismissed) }
        )

        is RestoreStage.Done -> AppAlertDialog(
            title = stringResource(R.string.settings_restore_done_title),
            message = restoreReportText(stage.report),
            confirmLabel = stringResource(R.string.settings_restore_done_action),
            onConfirm = { onAction(SettingsAction.OnRestoreDismissed) },
            onDismiss = { onAction(SettingsAction.OnRestoreDismissed) }
        )

        RestoreStage.Idle, RestoreStage.Reading, RestoreStage.Writing -> Unit
    }
}

/**
 * The result, including every identifier the restore declined to repoint.
 *
 * The conflicts are listed rather than counted because each one is a mapping the user will find
 * behaving differently from the device the backup came from, and a bare number gives them nothing
 * to go and look at.
 */
@Composable
private fun restoreReportText(report: RestoreReport): String {
    val summary = stringResource(
        R.string.settings_restore_done_message,
        report.transactions,
        report.duplicatesFlagged,
        report.payees,
        report.payeeIdentifiers,
        report.sessions,
        report.categoriesInserted,
        report.categoriesReused
    )
    if (report.identifierConflicts.isEmpty()) return summary

    // getString rather than stringResource: joinToString's lambda is not inline, so a composable
    // call inside it would not compile.
    val context = LocalContext.current
    // Restoring a backup onto the account it came from makes every mapped name a conflict, which on
    // a real account is dozens of them — more than a dialog can show, and past the first few the
    // list stops telling the reader anything the count does not.
    val shown = report.identifierConflicts.take(MAX_LISTED_CONFLICTS)
    val lines = shown.joinToString("\n") { conflict ->
        context.getString(
            R.string.settings_restore_done_conflict_line,
            conflict.normalizedName,
            conflict.keptPayeeAlias,
            conflict.filePayeeAlias
        )
    } + if (report.identifierConflicts.size > shown.size) {
        "\n" + context.getString(
            R.string.settings_restore_done_conflicts_more,
            report.identifierConflicts.size - shown.size
        )
    } else {
        ""
    }
    return summary + stringResource(
        R.string.settings_restore_done_conflicts,
        report.identifierConflicts.size,
        lines
    )
}

/**
 * A settings entry. [onClick] is null for entries that exist but do nothing yet, which also
 * removes the ripple so the row doesn't look tappable.
 */
@Composable
private fun SettingsRow(
    icon: ImageVector,
    title: String,
    onClick: (() -> Unit)?,
    supporting: String? = null,
    trailing: (@Composable () -> Unit)? = null
) {
    val enabled = onClick != null
    ListRow(
        title = title,
        supporting = supporting,
        dimmed = !enabled,
        leading = {
            Icon(
                imageVector = icon,
                contentDescription = null,
                tint = if (enabled) {
                    MaterialTheme.colorScheme.onSurfaceVariant
                } else {
                    MaterialTheme.colorScheme.outline
                },
                modifier = Modifier.size(24.dp)
            )
        },
        trailing = trailing,
        modifier = if (enabled) Modifier.clickable(onClick = onClick) else Modifier
    )
}

package com.madtitan94.transactionsparser.feature.settings.presentation

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.madtitan94.transactionsparser.core.domain.analytics.AnalyticsEvent
import com.madtitan94.transactionsparser.core.domain.analytics.AnalyticsParams
import com.madtitan94.transactionsparser.core.domain.analytics.AnalyticsTracker
import com.madtitan94.transactionsparser.core.domain.backup.BackupPreview
import com.madtitan94.transactionsparser.core.domain.backup.CreateBackupUseCase
import com.madtitan94.transactionsparser.core.domain.backup.ReadBackupUseCase
import com.madtitan94.transactionsparser.core.domain.backup.RestoreBackupUseCase
import com.madtitan94.transactionsparser.core.domain.backup.RestoreReport
import com.madtitan94.transactionsparser.core.domain.datasource.DocumentWriter
import com.madtitan94.transactionsparser.core.domain.datasource.SessionStorage
import com.madtitan94.transactionsparser.core.domain.datasource.TransactionLocalDataSource
import com.madtitan94.transactionsparser.core.domain.export.TransactionCsv
import com.madtitan94.transactionsparser.core.domain.util.Result
import com.madtitan94.transactionsparser.core.presentation.UiText
import com.madtitan94.transactionsparser.core.presentation.toUiText
import com.madtitan94.transactionsparser.feature.settings.domain.ThemePreference
import com.madtitan94.transactionsparser.feature.settings.domain.ThemeStorage
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.receiveAsFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import java.time.LocalDate

data class SettingsState(
    val email: String = "",
    val name: String = "",
    val photoUrl: String? = null,
    val showLogoutConfirm: Boolean = false,
    val isExporting: Boolean = false,
    val isBackingUp: Boolean = false,
    val restore: RestoreStage = RestoreStage.Idle,
    val theme: ThemePreference = ThemePreference.SYSTEM,
    val showThemePicker: Boolean = false
)

/**
 * Where a restore has got to.
 *
 * Modelled as a sequence rather than as a handful of booleans because the order is the safety
 * property: the file is read and fully validated before the user is asked anything, the account
 * warning comes before the summary, and nothing is written until [Confirm] is answered.
 */
sealed interface RestoreStage {
    data object Idle : RestoreStage

    /** Reading and validating the picked file. Still nothing written. */
    data object Reading : RestoreStage

    /** The file belongs to another account, which the user has to acknowledge before seeing more. */
    data class AccountMismatch(val preview: BackupPreview) : RestoreStage

    /** What the file contains, for the user to accept or reject. Still nothing written. */
    data class Confirm(val preview: BackupPreview) : RestoreStage

    data object Writing : RestoreStage

    data class Done(val report: RestoreReport) : RestoreStage
}

/** The stages with nothing for the user to do but wait. */
val RestoreStage.isBusy: Boolean
    get() = this is RestoreStage.Reading || this is RestoreStage.Writing

sealed interface SettingsAction {
    data object OnLogoutClick : SettingsAction
    data object OnConfirmLogout : SettingsAction
    data object OnDismissLogoutConfirm : SettingsAction
    data object OnExportClick : SettingsAction
    /** The picker returned a destination. */
    data class OnExportDestinationChosen(val destination: String) : SettingsAction
    /** The user backed out of the picker — not an error, so it only clears the busy state. */
    data object OnExportCancelled : SettingsAction
    data object OnBackupClick : SettingsAction
    data class OnBackupDestinationChosen(val destination: String) : SettingsAction
    data object OnBackupCancelled : SettingsAction
    data object OnRestoreClick : SettingsAction
    /** The picker returned a file to read. Nothing is written until [OnRestoreConfirmed]. */
    data class OnRestoreSourceChosen(val source: String) : SettingsAction
    /** The user accepted that the file belongs to a different account. */
    data object OnRestoreAccountAccepted : SettingsAction
    data object OnRestoreConfirmed : SettingsAction
    /** Backing out at any point before the write, and dismissing the report after it. */
    data object OnRestoreDismissed : SettingsAction
    data object OnThemeClick : SettingsAction
    data class OnThemeSelected(val preference: ThemePreference) : SettingsAction
    data object OnThemePickerDismissed : SettingsAction
}

sealed interface SettingsEvent {
    data class ShowMessage(val message: UiText) : SettingsEvent
    /** Asks the screen to open the system file picker, since only it can launch one. */
    data class LaunchExportPicker(val suggestedFileName: String) : SettingsEvent
    data class LaunchBackupPicker(val suggestedFileName: String) : SettingsEvent
    data object LaunchRestorePicker : SettingsEvent
}

class SettingsViewModel(
    private val sessionStorage: SessionStorage,
    private val transactions: TransactionLocalDataSource,
    private val documentWriter: DocumentWriter,
    private val createBackup: CreateBackupUseCase,
    private val readBackup: ReadBackupUseCase,
    private val restoreBackup: RestoreBackupUseCase,
    private val themeStorage: ThemeStorage,
    private val analytics: AnalyticsTracker
) : ViewModel() {

    private val _state = MutableStateFlow(SettingsState())
    val state = _state.asStateFlow()

    private val _events = Channel<SettingsEvent>()
    val events = _events.receiveAsFlow()

    init {
        observeSession()
        observeTheme()
    }

    // Observed rather than read once, so the row still shows the truth if the preference is
    // changed somewhere else while this screen is open.
    private fun observeTheme() {
        viewModelScope.launch {
            themeStorage.observeTheme().collect { preference ->
                _state.update { it.copy(theme = preference) }
            }
        }
    }

    private fun observeSession() {
        viewModelScope.launch {
            sessionStorage.observeSession().collect { session ->
                _state.update {
                    it.copy(
                        email = session?.email.orEmpty(),
                        name = session?.name.orEmpty(),
                        photoUrl = session?.photoUrl
                    )
                }
            }
        }
    }

    fun onAction(action: SettingsAction) {
        when (action) {
            SettingsAction.OnLogoutClick -> _state.update { it.copy(showLogoutConfirm = true) }
            SettingsAction.OnDismissLogoutConfirm -> _state.update { it.copy(showLogoutConfirm = false) }
            SettingsAction.OnConfirmLogout -> {
                _state.update { it.copy(showLogoutConfirm = false) }
                // Raised before the session is cleared, so it still carries the account it belongs
                // to. Afterwards there is no identity left and the event lands anonymous — which
                // makes "who signs out" unanswerable, the one question the event exists for.
                analytics.track(AnalyticsEvent.LoggedOut)
                viewModelScope.launch { sessionStorage.clear() }
            }
            SettingsAction.OnExportClick -> startExport()
            is SettingsAction.OnExportDestinationChosen -> export(action.destination)
            SettingsAction.OnExportCancelled -> _state.update { it.copy(isExporting = false) }
            SettingsAction.OnBackupClick -> startBackup()
            is SettingsAction.OnBackupDestinationChosen -> backup(action.destination)
            SettingsAction.OnBackupCancelled -> _state.update { it.copy(isBackingUp = false) }
            SettingsAction.OnRestoreClick -> startRestore()
            is SettingsAction.OnRestoreSourceChosen -> readRestore(action.source)
            SettingsAction.OnRestoreAccountAccepted -> acceptRestoreAccount()
            SettingsAction.OnRestoreConfirmed -> writeRestore()
            SettingsAction.OnRestoreDismissed -> _state.update { it.copy(restore = RestoreStage.Idle) }
            SettingsAction.OnThemeClick -> _state.update { it.copy(showThemePicker = true) }
            SettingsAction.OnThemePickerDismissed -> _state.update { it.copy(showThemePicker = false) }
            is SettingsAction.OnThemeSelected -> selectTheme(action.preference)
        }
    }

    private fun selectTheme(preference: ThemePreference) {
        // The picker closes immediately and the state is updated here rather than waiting for the
        // write to come back through observeTheme, so the theme changes under the user's finger
        // instead of a frame or two later.
        _state.update { it.copy(theme = preference, showThemePicker = false) }
        viewModelScope.launch { themeStorage.setTheme(preference) }
    }

    private fun startExport() {
        if (_state.value.isExporting) return
        _state.update { it.copy(isExporting = true) }
        viewModelScope.launch {
            _events.send(SettingsEvent.LaunchExportPicker(suggestedFileName()))
        }
    }

    private fun export(destination: String) {
        viewModelScope.launch {
            val rows = when (val result = transactions.exportRows()) {
                is Result.Error -> {
                    finishExport(result.error.toUiText())
                    return@launch
                }
                is Result.Success -> result.data
            }

            // An empty export is still written rather than refused: a file with only a header row
            // is an honest answer to "export my data" when there is none, and refusing would look
            // the same as a failure.
            val message = when (val written = documentWriter.write(destination, TransactionCsv.build(rows))) {
                is Result.Error -> written.error.toUiText()
                is Result.Success -> {
                    // Only once the file is actually written. Counting the attempt would report
                    // exports that failed at the picker as data that left the app.
                    analytics.track(
                        AnalyticsEvent.DataExported(
                            format = AnalyticsParams.FORMAT_CSV,
                            rowCount = rows.size
                        )
                    )
                    UiText.StringResource(R.string.settings_export_done, arrayOf(rows.size))
                }
            }
            finishExport(message)
        }
    }

    private suspend fun finishExport(message: UiText) {
        _state.update { it.copy(isExporting = false) }
        _events.send(SettingsEvent.ShowMessage(message))
    }

    private fun startBackup() {
        if (_state.value.isBackingUp) return
        _state.update { it.copy(isBackingUp = true) }
        viewModelScope.launch {
            _events.send(SettingsEvent.LaunchBackupPicker(suggestedBackupFileName()))
        }
    }

    private fun backup(destination: String) {
        viewModelScope.launch {
            // The transaction count is the number the user can check against the app, so it is
            // what the confirmation reports — the other five tables are along for the ride and
            // saying "1,247 rows" would be a number with nothing to compare it to.
            val message = when (val result = createBackup(destination)) {
                is Result.Error -> result.error.toUiText()
                is Result.Success -> {
                    analytics.track(
                        AnalyticsEvent.DataExported(
                            format = AnalyticsParams.FORMAT_BACKUP,
                            rowCount = result.data.transactions
                        )
                    )
                    UiText.StringResource(
                        R.string.settings_backup_done,
                        arrayOf(result.data.transactions)
                    )
                }
            }
            _state.update { it.copy(isBackingUp = false) }
            _events.send(SettingsEvent.ShowMessage(message))
        }
    }

    private fun startRestore() {
        if (_state.value.restore != RestoreStage.Idle) return
        viewModelScope.launch { _events.send(SettingsEvent.LaunchRestorePicker) }
    }

    private fun readRestore(source: String) {
        _state.update { it.copy(restore = RestoreStage.Reading) }
        viewModelScope.launch {
            when (val preview = readBackup(source)) {
                is Result.Error -> {
                    _state.update { it.copy(restore = RestoreStage.Idle) }
                    _events.send(SettingsEvent.ShowMessage(preview.error.toUiText()))
                }
                // Two stops rather than one: a file from another account is a different decision
                // from "is this the right backup", and folding them together would let someone
                // agree to the counts while missing whose data they are.
                is Result.Success -> _state.update {
                    it.copy(
                        restore = if (preview.data.isDifferentAccount) {
                            RestoreStage.AccountMismatch(preview.data)
                        } else {
                            RestoreStage.Confirm(preview.data)
                        }
                    )
                }
            }
        }
    }

    private fun acceptRestoreAccount() {
        val stage = _state.value.restore as? RestoreStage.AccountMismatch ?: return
        _state.update { it.copy(restore = RestoreStage.Confirm(stage.preview)) }
    }

    private fun writeRestore() {
        val stage = _state.value.restore as? RestoreStage.Confirm ?: return
        _state.update { it.copy(restore = RestoreStage.Writing) }
        viewModelScope.launch {
            when (val result = restoreBackup(stage.preview.file)) {
                is Result.Error -> {
                    // Nothing was written — the whole restore is one transaction — so dropping
                    // back to Idle leaves the account exactly as it was.
                    _state.update { it.copy(restore = RestoreStage.Idle) }
                    _events.send(SettingsEvent.ShowMessage(result.error.toUiText()))
                }
                is Result.Success -> _state.update {
                    it.copy(restore = RestoreStage.Done(result.data))
                }
            }
        }
    }

    /** Dated so repeated exports don't silently overwrite each other in the picker's default spot. */
    private fun suggestedFileName(): String = "transactions-${LocalDate.now()}.csv"

    private fun suggestedBackupFileName(): String = "transactions-backup-${LocalDate.now()}.json"
}

package com.madtitan94.transactionsparser.feature.settings.presentation

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.madtitan94.transactionsparser.core.domain.analytics.AnalyticsEvent
import com.madtitan94.transactionsparser.core.domain.analytics.AnalyticsParams
import com.madtitan94.transactionsparser.core.domain.analytics.AnalyticsTracker
import com.madtitan94.transactionsparser.core.domain.backup.BackupPreview
import com.madtitan94.transactionsparser.core.domain.backup.CreateBackupUseCase
import com.madtitan94.transactionsparser.core.domain.backup.ReadBackupUseCase
import com.madtitan94.transactionsparser.core.domain.backup.RestoreBackupUseCase
import com.madtitan94.transactionsparser.core.domain.backup.RestoreReport
import com.madtitan94.transactionsparser.core.domain.datasource.DocumentWriter
import com.madtitan94.transactionsparser.core.domain.datasource.SessionStorage
import com.madtitan94.transactionsparser.core.domain.datasource.TransactionLocalDataSource
import com.madtitan94.transactionsparser.core.domain.export.TransactionCsv
import com.madtitan94.transactionsparser.core.domain.util.Result
import com.madtitan94.transactionsparser.core.presentation.UiText
import com.madtitan94.transactionsparser.core.presentation.toUiText
import com.madtitan94.transactionsparser.feature.settings.domain.DeleteAccountService
import com.madtitan94.transactionsparser.feature.settings.domain.ThemePreference
import com.madtitan94.transactionsparser.feature.settings.domain.ThemeStorage
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.receiveAsFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import java.time.LocalDate

data class SettingsState(
    val email: String = "",
    val name: String = "",
    val photoUrl: String? = null,
    val showLogoutConfirm: Boolean = false,
    val showDeleteAccountConfirm: Boolean = false,
    val isDeletingAccount: Boolean = false,
    val isExporting: Boolean = false,
    val isBackingUp: Boolean = false,
    val restore: RestoreStage = RestoreStage.Idle,
    val theme: ThemePreference = ThemePreference.SYSTEM,
    val showThemePicker: Boolean = false
)

/**
 * Where a restore has got to.
 *
 * Modelled as a sequence rather than as a handful of booleans because the order is the safety
 * property: the file is read and fully validated before the user is asked anything, the account
 * warning comes before the summary, and nothing is written until [Confirm] is answered.
 */
sealed interface RestoreStage {
    data object Idle : RestoreStage

    /** Reading and validating the picked file. Still nothing written. */
    data object Reading : RestoreStage

    /** The file belongs to another account, which the user has to acknowledge before seeing more. */
    data class AccountMismatch(val preview: BackupPreview) : RestoreStage

    /** What the file contains, for the user to accept or reject. Still nothing written. */
    data class Confirm(val preview: BackupPreview) : RestoreStage

    data object Writing : RestoreStage

    data class Done(val report: RestoreReport) : RestoreStage
}

/** The stages with nothing for the user to do but wait. */
val RestoreStage.isBusy: Boolean
    get() = this is RestoreStage.Reading || this is RestoreStage.Writing

sealed interface SettingsAction {
    data object OnLogoutClick : SettingsAction
    data object OnConfirmLogout : SettingsAction
    data object OnDismissLogoutConfirm : SettingsAction
    data object OnDeleteAccountClick : SettingsAction
    data object OnConfirmDeleteAccount : SettingsAction
    data object OnDismissDeleteAccountConfirm : SettingsAction
    data object OnExportClick : SettingsAction
    /** The picker returned a destination. */
    data class OnExportDestinationChosen(val destination: String) : SettingsAction
    /** The user backed out of the picker — not an error, so it only clears the busy state. */
    data object OnExportCancelled : SettingsAction
    data object OnBackupClick : SettingsAction
    data class OnBackupDestinationChosen(val destination: String) : SettingsAction
    data object OnBackupCancelled : SettingsAction
    data object OnRestoreClick : SettingsAction
    /** The picker returned a file to read. Nothing is written until [OnRestoreConfirmed]. */
    data class OnRestoreSourceChosen(val source: String) : SettingsAction
    /** The user accepted that the file belongs to a different account. */
    data object OnRestoreAccountAccepted : SettingsAction
    data object OnRestoreConfirmed : SettingsAction
    /** Backing out at any point before the write, and dismissing the report after it. */
    data object OnRestoreDismissed : SettingsAction
    data object OnThemeClick : SettingsAction
    data class OnThemeSelected(val preference: ThemePreference) : SettingsAction
    data object OnThemePickerDismissed : SettingsAction
}

sealed interface SettingsEvent {
    data class ShowMessage(val message: UiText) : SettingsEvent
    /** Asks the screen to open the system file picker, since only it can launch one. */
    data class LaunchExportPicker(val suggestedFileName: String) : SettingsEvent
    data class LaunchBackupPicker(val suggestedFileName: String) : SettingsEvent
    data object LaunchRestorePicker : SettingsEvent
}

class SettingsViewModel(
    private val sessionStorage: SessionStorage,
    private val transactions: TransactionLocalDataSource,
    private val documentWriter: DocumentWriter,
    private val createBackup: CreateBackupUseCase,
    private val readBackup: ReadBackupUseCase,
    private val restoreBackup: RestoreBackupUseCase,
    private val deleteAccount: DeleteAccountService,
    private val themeStorage: ThemeStorage,
    private val analytics: AnalyticsTracker
) : ViewModel() {

    private val _state = MutableStateFlow(SettingsState())
    val state = _state.asStateFlow()

    private val _events = Channel<SettingsEvent>()
    val events = _events.receiveAsFlow()

    init {
        observeSession()
        observeTheme()
    }

    // Observed rather than read once, so the row still shows the truth if the preference is
    // changed somewhere else while this screen is open.
    private fun observeTheme() {
        viewModelScope.launch {
            themeStorage.observeTheme().collect { preference ->
                _state.update { it.copy(theme = preference) }
            }
        }
    }

    private fun observeSession() {
        viewModelScope.launch {
            sessionStorage.observeSession().collect { session ->
                _state.update {
                    it.copy(
                        email = session?.email.orEmpty(),
                        name = session?.name.orEmpty(),
                        photoUrl = session?.photoUrl
                    )
                }
            }
        }
    }

    fun onAction(action: SettingsAction) {
        when (action) {
            SettingsAction.OnLogoutClick -> _state.update { it.copy(showLogoutConfirm = true) }
            SettingsAction.OnDismissLogoutConfirm -> _state.update { it.copy(showLogoutConfirm = false) }
            SettingsAction.OnConfirmLogout -> {
                _state.update { it.copy(showLogoutConfirm = false) }
                // Raised before the session is cleared, so it still carries the account it belongs
                // to. Afterwards there is no identity left and the event lands anonymous — which
                // makes "who signs out" unanswerable, the one question the event exists for.
                analytics.track(AnalyticsEvent.LoggedOut)
                viewModelScope.launch { sessionStorage.clear() }
            }
            SettingsAction.OnDeleteAccountClick -> {
                if (_state.value.isDeletingAccount) return
                _state.update { it.copy(showDeleteAccountConfirm = true) }
            }
            SettingsAction.OnDismissDeleteAccountConfirm -> {
                _state.update { it.copy(showDeleteAccountConfirm = false) }
            }
            SettingsAction.OnConfirmDeleteAccount -> {
                if (_state.value.isDeletingAccount) return
                _state.update { it.copy(showDeleteAccountConfirm = false, isDeletingAccount = true) }
                viewModelScope.launch {
                    when (val result = deleteAccount.deleteAccount()) {
                        is Result.Success -> _state.update { it.copy(isDeletingAccount = false) }
                        is Result.Error -> {
                            _state.update { it.copy(isDeletingAccount = false) }
                            _events.send(SettingsEvent.ShowMessage(result.error.toUiText()))
                        }
                    }
                }
            }
            SettingsAction.OnExportClick -> startExport()
            is SettingsAction.OnExportDestinationChosen -> export(action.destination)
            SettingsAction.OnExportCancelled -> _state.update { it.copy(isExporting = false) }
            SettingsAction.OnBackupClick -> startBackup()
            is SettingsAction.OnBackupDestinationChosen -> backup(action.destination)
            SettingsAction.OnBackupCancelled -> _state.update { it.copy(isBackingUp = false) }
            SettingsAction.OnRestoreClick -> startRestore()
            is SettingsAction.OnRestoreSourceChosen -> readRestore(action.source)
            SettingsAction.OnRestoreAccountAccepted -> acceptRestoreAccount()
            SettingsAction.OnRestoreConfirmed -> writeRestore()
            SettingsAction.OnRestoreDismissed -> _state.update { it.copy(restore = RestoreStage.Idle) }
            SettingsAction.OnThemeClick -> _state.update { it.copy(showThemePicker = true) }
            SettingsAction.OnThemePickerDismissed -> _state.update { it.copy(showThemePicker = false) }
            is SettingsAction.OnThemeSelected -> selectTheme(action.preference)
        }
    }

    private fun selectTheme(preference: ThemePreference) {
        // The picker closes immediately and the state is updated here rather than waiting for the
        // write to come back through observeTheme, so the theme changes under the user's finger
        // instead of a frame or two later.
        _state.update { it.copy(theme = preference, showThemePicker = false) }
        viewModelScope.launch { themeStorage.setTheme(preference) }
    }

    private fun startExport() {
        if (_state.value.isExporting) return
        _state.update { it.copy(isExporting = true) }
        viewModelScope.launch {
            _events.send(SettingsEvent.LaunchExportPicker(suggestedFileName()))
        }
    }

    private fun export(destination: String) {
        viewModelScope.launch {
            val rows = when (val result = transactions.exportRows()) {
                is Result.Error -> {
                    finishExport(result.error.toUiText())
                    return@launch
                }
                is Result.Success -> result.data
            }

            // An empty export is still written rather than refused: a file with only a header row
            // is an honest answer to "export my data" when there is none, and refusing would look
            // the same as a failure.
            val message = when (val written = documentWriter.write(destination, TransactionCsv.build(rows))) {
                is Result.Error -> written.error.toUiText()
                is Result.Success -> {
                    // Only once the file is actually written. Counting the attempt would report
                    // exports that failed at the picker as data that left the app.
                    analytics.track(
                        AnalyticsEvent.DataExported(
                            format = AnalyticsParams.FORMAT_CSV,
                            rowCount = rows.size
                        )
                    )
                    UiText.StringResource(R.string.settings_export_done, arrayOf(rows.size))
                }
            }
            finishExport(message)
        }
    }

    private suspend fun finishExport(message: UiText) {
        _state.update { it.copy(isExporting = false) }
        _events.send(SettingsEvent.ShowMessage(message))
    }

    private fun startBackup() {
        if (_state.value.isBackingUp) return
        _state.update { it.copy(isBackingUp = true) }
        viewModelScope.launch {
            _events.send(SettingsEvent.LaunchBackupPicker(suggestedBackupFileName()))
        }
    }

    private fun backup(destination: String) {
        viewModelScope.launch {
            // The transaction count is the number the user can check against the app, so it is
            // what the confirmation reports — the other five tables are along for the ride and
            // saying "1,247 rows" would be a number with nothing to compare it to.
            val message = when (val result = createBackup(destination)) {
                is Result.Error -> result.error.toUiText()
                is Result.Success -> {
                    analytics.track(
                        AnalyticsEvent.DataExported(
                            format = AnalyticsParams.FORMAT_BACKUP,
                            rowCount = result.data.transactions
                        )
                    )
                    UiText.StringResource(
                        R.string.settings_backup_done,
                        arrayOf(result.data.transactions)
                    )
                }
            }
            _state.update { it.copy(isBackingUp = false) }
            _events.send(SettingsEvent.ShowMessage(message))
        }
    }

    private fun startRestore() {
        if (_state.value.restore != RestoreStage.Idle) return
        viewModelScope.launch { _events.send(SettingsEvent.LaunchRestorePicker) }
    }

    private fun readRestore(source: String) {
        _state.update { it.copy(restore = RestoreStage.Reading) }
        viewModelScope.launch {
            when (val preview = readBackup(source)) {
                is Result.Error -> {
                    _state.update { it.copy(restore = RestoreStage.Idle) }
                    _events.send(SettingsEvent.ShowMessage(preview.error.toUiText()))
                }
                // Two stops rather than one: a file from another account is a different decision
                // from "is this the right backup", and folding them together would let someone
                // agree to the counts while missing whose data they are.
                is Result.Success -> _state.update {
                    it.copy(
                        restore = if (preview.data.isDifferentAccount) {
                            RestoreStage.AccountMismatch(preview.data)
                        } else {
                            RestoreStage.Confirm(preview.data)
                        }
                    )
                }
            }
        }
    }

    private fun acceptRestoreAccount() {
        val stage = _state.value.restore as? RestoreStage.AccountMismatch ?: return
        _state.update { it.copy(restore = RestoreStage.Confirm(stage.preview)) }
    }

    private fun writeRestore() {
        val stage = _state.value.restore as? RestoreStage.Confirm ?: return
        _state.update { it.copy(restore = RestoreStage.Writing) }
        viewModelScope.launch {
            when (val result = restoreBackup(stage.preview.file)) {
                is Result.Error -> {
                    // Nothing was written — the whole restore is one transaction — so dropping
                    // back to Idle leaves the account exactly as it was.
                    _state.update { it.copy(restore = RestoreStage.Idle) }
                    _events.send(SettingsEvent.ShowMessage(result.error.toUiText()))
                }
                is Result.Success -> _state.update {
                    it.copy(restore = RestoreStage.Done(result.data))
                }
            }
        }
    }

    /** Dated so repeated exports don't silently overwrite each other in the picker's default spot. */
    private fun suggestedFileName(): String = "transactions-${LocalDate.now()}.csv"

    private fun suggestedBackupFileName(): String = "transactions-backup-${LocalDate.now()}.json"
}
